package lenses

import (
	"time"

	"github.com/bonjoski/coppermind/pkg/brain"
)

// Finding represents an individual finding or critique generated by a lens.
type Finding struct {
	Severity string `json:"severity"`
	Category string `json:"category"`
	Summary  string `json:"summary"`
	TargetID string `json:"target_id,omitempty"`
	Evidence string `json:"evidence,omitempty"`
}

// ModelResponse represents the strict JSON schema returned by LiteLLM inference.
type ModelResponse struct {
	Findings []Finding `json:"findings"`
}

// ReflectRequest configures an on-demand reflection pass over memories.
type ReflectRequest struct {
	Lens           string              `json:"lens"` // "all" or specific lens name
	Since          time.Duration       `json:"since"`
	CrossVault     bool                `json:"cross_vault"`
	Project        string              `json:"project"`
	SessionID      string              `json:"session_id"`
	Limit          int                 `json:"limit,omitempty"`
	CandidateNodes []*brain.MemoryNode `json:"candidate_nodes,omitempty"`
}

// ReflectResult summarizes the outcome of a lens reflection run.
type ReflectResult struct {
	Observations   []*brain.MemoryNode `json:"observations"`
	EvaluatedCount int                 `json:"evaluated_count"`
	SkippedCount   int                 `json:"skipped_count"`
	Errors         []string            `json:"errors,omitempty"`
}
